impl From<DeleteSurface> for Operation{fn from(p:DeleteSurface)->Self{Self::Delete(p)}}impl From<crate::CreateSurface> for Operation{fn from(p:crate::CreateSurface)->Self{Self::Surface(p)}}impl From<crate::CreateFenestration> for Operation{fn from(p:crate::CreateFenestration)->Self{Self::Fenestration(p)}}impl From<crate::ReplaceFenestrationVertices> for Operation{fn from(p:crate::ReplaceFenestrationVertices)->Self{Self::Vertices(p)}}impl From<crate::ConnectSurfaces> for Operation{fn from(p:crate::ConnectSurfaces)->Self{Self::Pair(p)}}
impl protocol::Mutation<EnergyModelSnapshot> for Operation{type Diff=crate::diff::original::EnergyModelDiff;const DESCRIPTORS:&'static[protocol::MutationLeafDescriptor]=&[<DeleteSurface as protocol::MutationLeaf>::DESCRIPTOR];fn descriptor(&self)->&'static protocol::MutationLeafDescriptor{match self{Self::Delete(_)=>&<DeleteSurface as protocol::MutationLeaf>::DESCRIPTOR,Self::Surface(_)=>&<crate::CreateSurface as protocol::MutationLeaf>::DESCRIPTOR,Self::Fenestration(_)=>&<crate::CreateFenestration as protocol::MutationLeaf>::DESCRIPTOR,Self::Vertices(_)=>&<crate::ReplaceFenestrationVertices as protocol::MutationLeaf>::DESCRIPTOR,Self::Pair(_)=>&<crate::ConnectSurfaces as protocol::MutationLeaf>::DESCRIPTOR}}}
#[test]fn original_surface_cascade_retains_all_original_child_inverse_fields_rank_and_paid_cancellation(){laws::run::<DeleteSurface,Operation>(include_str!("🧫️fixtures/🔣️.json"),|post|{let g=post.model.geometry.get();let mut ids:Vec<u32>=(0..g.surfaces.len()).map(|i|g.surfaces.get(i).unwrap().id.0).collect();ids.extend((0..g.fenestrations.len()).map(|i|g.fenestrations.get(i).unwrap().id.0));for i in 0..g.adjacency_pairs.len(){let p=g.adjacency_pairs.get(i).unwrap();ids.extend([p.surface_a_id.0,p.surface_b_id.0]);}ids},|m|match m{Operation::Surface(p)=>p.id.0,Operation::Fenestration(p)=>p.id.0,Operation::Vertices(p)=>p.id.0,Operation::Pair(p)=>p.surface_a_id.0,_=>panic!("original cascade emits only recreation intents")});}

#[test]fn original_aggregate_target_dispatch_preserves_actual_pair_and_entity_fragments_without_allocation(){use semio_s_artifact_energy_model_native_mutations::target::ArtifactOperationTargets;let p=crate::ConnectSurfaces{surface_a_id:crate::model::EntityId(4294967295),surface_b_id:crate::model::EntityId(7),index:None};let op=Operation::Pair(p);let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{assert_eq!(op.len(),2);assert_eq!(op.segment_len(0).unwrap(),10);let mut bytes=[0u8;32];let n=op.read_segment(0,0,&mut bytes).unwrap();assert_eq!(&bytes[..n],b"4294967295");assert!(op.segment_len(2).is_err());let p=Operation::Delete(DeleteSurface{id:crate::model::EntityId(7)});assert_eq!(p.len(),1);assert_eq!(p.read_segment(0,0,&mut bytes).unwrap(),1);assert_eq!(bytes[0],b'7');});assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
